                var tocCls = 'toc-item w-full text-left px-3 py-2 rounded text-xs ' + CF_MAT_THEME.tocHover + ' transition-colors ' + (idx === 0 ? CF_MAT_THEME.tocActive : CF_MAT_THEME.tocInactive);
